#!/usr/bin/env bash
# run-tasks.sh — generated by `onp-spec plan login-secret-release` at 2026-10-24 02:12
# do NOT edit by hand: if tasks.md or the config changed, regenerate the plan.
#
# usage:
#   bash run-tasks.sh                  everything (waves → sequential → gate)
#   bash run-tasks.sh --track <id>     re-runs ONE track (+ merge + gate)
#   bash run-tasks.sh --seq <T-xxx>    re-runs ONE sequential task
#   bash run-tasks.sh --gate           only the gate (verify + audit)
#   bash run-tasks.sh --list           shows tracks, tasks and states
#   (add --no-gate to skip the gate at the end)
#
# summary of what is going on, at any time: onp-spec summary login-secret-release
set -u
set -o pipefail

RUN_ID='open-hello-login-secret-release-mvlrk1e7'
FEATURE='login-secret-release'
BASE_BRANCH='spec/login-secret-release'
ENGINE='/home/eduresser/.claude/skills/onp-spec-driven-en/scripts/onp-spec.mjs'
CLAUDE_FLAGS=(--permission-mode acceptEdits --allowedTools 'Bash(git add:*),Bash(git commit:*),Bash(git status:*),Bash(git diff:*),Bash(git log:*),Bash(cargo:*)')
STREAM_FLAGS=(--output-format stream-json --verbose)
FAILURES=""
WITH_GATE=1
SUMMARY_MODEL='claude-haiku-4-5'
SUMMARY_PID=""

green()  { printf '\033[32m%s\033[0m\n' "$*"; }
red()    { printf '\033[31m%s\033[0m\n' "$*"; }
yellow() { printf '\033[33m%s\033[0m\n' "$*"; }
info()   { printf '· %s\n' "$*"; }
fail()   { red "✘ $*"; exit 1; }

# events go to the GLOBAL ledger (~/.onp-spec/panel/ledger.jsonl):
# one file for all projects — it is what onp-spec summary reads
event() { node "$ENGINE" event --run "$RUN_ID" "$@" >/dev/null 2>&1 || true; }

# ── environment (every mode goes through here) ───────────────────────
prepare_env() {
  command -v git >/dev/null 2>&1 || fail "git not found"
  command -v node >/dev/null 2>&1 || fail "node not found"
  command -v claude >/dev/null 2>&1 || fail "Claude Code CLI (claude) not found — install it or follow the manual mode in execution-plan.md"
  TOPLEVEL=$(git rev-parse --show-toplevel 2>/dev/null) || fail "outside a git repository"
  cd "$TOPLEVEL" || exit 1
  # artifacts just generated by `onp-spec plan` are expected noise:
  # if they are the ONLY noise, the script commits them itself; anything else aborts
  if [ -n "$(git status --porcelain)" ]; then
    if [ -z "$(git status --porcelain | grep -v -e 'execution-plan\.' -e 'plan\.json' -e 'run-tasks\.sh')" ]; then
      git add -A
      git commit -q -m "execution plan: $FEATURE (generated artifacts)"
      info "plan artifacts committed"
    else
      fail "tree dirty beyond the plan artifacts — commit or git stash first (the worktrees start from the last commit)"
    fi
  fi
  git ls-files --error-unmatch -- '.spec/features/login-secret-release/spec.md' >/dev/null 2>&1 || fail "spec.md is not committed — the track worktrees need it in git"
  CURRENT=$(git rev-parse --abbrev-ref HEAD)
  [ "$CURRENT" != "HEAD" ] || fail "detached HEAD — switch to a branch"
  if [ "$CURRENT" != "$BASE_BRANCH" ]; then
    if git show-ref --verify --quiet "refs/heads/$BASE_BRANCH"; then
      git checkout -q "$BASE_BRANCH" || fail "could not switch to $BASE_BRANCH"
    else
      git checkout -q -b "$BASE_BRANCH" || fail "could not create $BASE_BRANCH"
    fi
    info "work branch: $BASE_BRANCH (from $CURRENT)"
  fi
  git worktree prune
  LOG_DIR="$(dirname "$TOPLEVEL")/onp-worktrees/open-hello-login-secret-release-logs"
  WT_BASE="$(dirname "$TOPLEVEL")/onp-worktrees/open-hello-login-secret-release"
  STREAMS_DIR="${ONP_SPEC_HOME:-$HOME/.onp-spec}/panel/streams/$RUN_ID"
  mkdir -p "$LOG_DIR" "$STREAMS_DIR"
}

# clean worktree even after a failed attempt
prepare_worktree() { # $1=track $2=branch $3=worktree
  git worktree prune
  if [ -e "$3" ]; then git worktree remove --force "$3" >/dev/null 2>&1; rm -rf "$3"; fi
  if git show-ref --verify --quiet "refs/heads/$2"; then git branch -D "$2" >/dev/null 2>&1; fi
  git worktree add "$3" -b "$2" >/dev/null 2>&1 || { red "✘ could not create the worktree of $1 at $3"; return 1; }
}

attempt() { # $1=track — counts re-runs (goes to the ledger)
  local file="$LOG_DIR/.attempt-$1"
  local n=1
  [ -f "$file" ] && n=$(( $(cat "$file") + 1 ))
  printf "%s" "$n" > "$file"
  printf "%s" "$n"
}

# one task = one headless claude session with a clean context.
# the session JSONL becomes the task stream in the ledger
run_task() { # $1=scope(track|seq) $2=T-xxx $3=prompt $4=model $5=effort
  local key="$1--$2"
  local stream="$STREAMS_DIR/$key.jsonl"
  event --type task --task "$2" --track "$1" --state running --stream "$key"
  info "$2 — claude -p ($4 · $5) · stream: $key"
  if claude -p "$3" --model "$4" --effort "$5" "${STREAM_FLAGS[@]}" "${CLAUDE_FLAGS[@]}" > "$stream" 2>>"$LOG_DIR/$1.log"; then
    event --type task --task "$2" --track "$1" --state done --stream "$key"
    node "$ENGINE" stream-summary "$RUN_ID" "$key" 2>/dev/null || true
    return 0
  fi
  event --type task --task "$2" --track "$1" --state failed --stream "$key"
  node "$ENGINE" stream-summary "$RUN_ID" "$key" 2>/dev/null || true
  return 1
}

merge_track() { # $1=track $2=branch $3=worktree $4=track-exit
  if [ "$4" -ne 0 ]; then
    event --type track --track "$1" --state failed
    red "✘ $1 failed (log: $LOG_DIR/$1.log) — worktree kept for inspection: $3"
    yellow "  re-run just this one: bash .spec/features/login-secret-release/run-tasks.sh --track $1"
    FAILURES="$FAILURES $1"; return 1
  fi
  event --type track --track "$1" --state merging
  if git merge --no-ff "$2" -m "merge $1 ($FEATURE)"; then
    git worktree remove --force "$3" >/dev/null 2>&1
    git branch -d "$2" >/dev/null 2>&1
    event --type track --track "$1" --state merged
    green "✔ $1 merged into $BASE_BRANCH"
  else
    git merge --abort >/dev/null 2>&1
    event --type track --track "$1" --state conflict
    red "✘ conflict merging $1 — resolve it by hand: git merge $2 (worktree kept: $3)"
    FAILURES="$FAILURES $1"; return 1
  fi
}

mark_done() { # $@=T-xxx
  for t in "$@"; do node "$ENGINE" task "$FEATURE" "$t" done >/dev/null || true; done
}

# ── overall progress summary: 1/min while the run is going ───────────
# written by AI (claude -p, no tools) with an engine fallback; it goes
# to the terminal and to the ledger — the agent relays the text in chat.
make_summary() {
  local ctx ai
  ctx=$(node "$ENGINE" summary "$FEATURE" --context 2>/dev/null) || ctx=""
  [ -n "$ctx" ] || return 0
  ai=$(claude -p "You narrate, for the product owner, a run of code tasks in progress. Mechanical state:

$ctx

Write the OVERALL PROGRESS SUMMARY: a single paragraph of 2 to 4 sentences, in plain English, saying what is happening now, what has already finished, what failed and whether the user needs to act. No markdown, no lists." --model "$SUMMARY_MODEL" 2>/dev/null)
  if [ -n "$ai" ]; then
    node "$ENGINE" summary "$FEATURE" --record --origin ai --text "$ai" >/dev/null 2>&1 || true
    printf '\n📣 summary (AI): %s\n' "$ai"
  else
    node "$ENGINE" summary "$FEATURE" --record >/dev/null 2>&1 || true
    printf '\n📣 summary: %s\n' "$(node "$ENGINE" summary "$FEATURE" 2>/dev/null)"
  fi
}

# kills the loop AND the child sleep — otherwise the sleep inherits stdout and
# whoever called the script through a pipe waits for EOF for up to 60s after exit
stop_summaries() {
  [ -n "$SUMMARY_PID" ] || return 0
  command -v pkill >/dev/null 2>&1 && pkill -P "$SUMMARY_PID" 2>/dev/null
  kill "$SUMMARY_PID" 2>/dev/null
  SUMMARY_PID=""
}

start_summaries() {
  ( while :; do sleep 60; make_summary; done ) &
  SUMMARY_PID=$!
  # on exit: stop the loop and record one last summary (the final state, from the engine)
  trap 'stop_summaries; node "$ENGINE" summary "$FEATURE" --record >/dev/null 2>&1 || true' EXIT
}

